 test((priv?'private':'web')+' role buys from the shared live shop without searching and preserves quote/payment checks',async()=>{const t=roleContext(),rpc=t.ctx.northMarketRpc;t.ctx.northShareValid=card=>card.version===1;t.ctx.msgs().unshift({type:'shopshare',role:'user',shopShare:{version:1,source:'cloud',id:'shop',name:'真人店'}});t.ctx.northMarketRpc=async(name,args,auth)=>{if(name==='role_catalog'||name==='list')throw Error('shared shop must not search');if(name==='shop'){t.events.push('direct-shop');assert.equal(args.p_id,'shop');return {shop:t.shop,products:t.shop.products};}return rpc(name,args,auth);};const result=await t.ctx.northPreferredRoleFood(t.c,'芋泥奶茶','19|真人店|温度:温的|温的|1','main',{messageId:'shared'});assert.equal(result.type,'marketfood');assert.equal(t.paid(),1);assert.ok(t.events.includes('quote'));assert.ok(t.events.includes('direct-shop'));assert.ok(!t.events.includes('role_catalog'));});
