 test((priv?'private':'web')+' short buy after a shared restaurant continues two discussed dishes to one paid receipt without search',async()=>{const t=roleContext(),now=Date.now(),share={version:1,source:'cloud',id:'shared',name:'闲云野鹤居'},messages=[{id:'share',role:'user',type:'shopshare',shopShare:share,time:now-60000},{id:'talk',role:'assistant',type:'text',content:'刚让先生给你点牛腩和小炒肉，转头自己偷偷下单草莓布蕾丝。刚才只查店铺菜单，不要下单。',time:now-50000},{id:'buy',role:'user',type:'text',content:'给我买',time:now}],products=[{id:'beef',name:'宋式番茄炖牛腩',price:3700,stock:5,available:true,specGroups:[]},{id:'pork',name:'山房小炒肉',price:3900,stock:5,available:true,specGroups:[]}];let paid=0,repairs=0;share.products=products;t.ctx.msgs=()=>messages;t.ctx.northShareValid=()=>true;t.ctx.northRoleModel=async(c,task,payload)=>{if(task.includes('本轮用户明确请求点餐')){repairs++;assert.equal(payload.sharedShopMenu.products.length,2);assert.match(payload.userRequest,/给我买/);assert.match(payload.userRequest,/牛腩和小炒肉/);return JSON.stringify({order:true,name:'宋式番茄炖牛腩',shop:'闲云野鹤居',specs:'无',temperature:'不适用',quantity:1});}if(task.includes('提取本轮'))return JSON.stringify({queries:['牛腩','小炒肉'],must:['牛腩'],quantity:1,preferences:[],items:[{name:'宋式番茄炖牛腩',must:['牛腩'],quantity:1,preferences:[]},{name:'山房小炒肉',must:['小炒肉'],quantity:1,preferences:[]}]});if(task.includes('从真实菜单筛选'))return JSON.stringify({shopId:'shared',primaryId:'beef',lines:products.map(p=>({productId:p.id,quantity:1,selections:{}}))});return JSON.stringify({message:'给你点好了。'});};t.ctx.northMarketRpc=async(name,args)=>{if(name==='role_catalog'||name==='list')throw Error('must open shared shop directly');if(name==='wallet')return {couple:{id:t.c.id,balance:100000,revision:1}};if(name==='shop')return {shop:{id:'shared',name:'闲云野鹤居',revision:1,minimum:4800,delivery:190},products};if(name==='coupons')return {coupons:[]};if(name==='quote')return {subtotal:7600,delivery:190,total:7790};if(name==='role_checkout'){paid++;assert.equal(args.p_total,7790);assert.equal(args.p_lines.length,2);return {order:{id:'two-dishes',shop_name:'闲云野鹤居',total:7790,subtotal:7600,delivery:190,items:products.map(p=>({...p,quantity:1,labels:[],total:p.price}))}};}if(name==='orders')return {orders:[]};throw Error(name);};const request=t.ctx.northRoleOrderRequest(t.c,'给我买');assert.match(request.text,/闲云野鹤居/);const meta={messageId:'buy',northRequestKey:request.anchorId,northUserRequest:request.text,northActualUserText:request.actualText,northCurrentRequest:true};const action=await t.ctx.northRoleEnsureAction(t.c,'[应用查询|闲云野鹤居]','给我买',meta);assert.ok(action.includes('[点外卖|'));assert.equal(repairs,1);const card=await t.ctx.northPreferredRoleFood(t.c,'宋式番茄炖牛腩','1|闲云野鹤居|无|不适用|1','main',meta);assert.equal(card.type,'marketfood',JSON.stringify(card));assert.equal(card.marketFood.order.items.length,2);assert.equal(paid,1);messages.push(card);await t.ctx.northPreferredRoleFood(t.c,'宋式番茄炖牛腩','1|闲云野鹤居|无|不适用|1','main',meta);assert.equal(paid,1);});
