 test((priv?'private':'web')+' real tomato beef without temperature specs reaches minimum with least stock-backed topup',async()=>{const t=roleContext(),beef={id:'beef',name:'宋式番茄炖牛腩',price:3700,stock:2,available:true,soldOut:false,specGroups:[]},rice={id:'rice',name:'青瓷米饭',price:200,stock:2,available:true,soldOut:false,specGroups:[]},lotus={id:'lotus',name:'桂花糯米藕',price:1000,stock:2,available:true,soldOut:false,specGroups:[]};const shop={id:'beef-shop',name:'闲云野鹤居',revision:1,minimum:4800,delivery:190,products:[beef,rice,lotus]};let calls=0,paid=0,quoted;t.ctx.msgs=()=>[{role:'user',type:'text',content:'那我要吃宋式番茄炖牛腩'}];t.ctx.northRoleModel=async()=>JSON.stringify({shopId:shop.id,primaryId:'beef',lines:[{productId:'beef',quantity:1,selections:{}}]});t.ctx.northMarketRpc=async(name,args)=>{calls++;if(name==='wallet')return {couple:{id:t.c.id,balance:8000,revision:1}};if(name==='role_catalog')return {shops:[shop]};if(name==='coupons')return {coupons:[]};if(name==='quote'){quoted=args.p_lines;const subtotal=args.p_lines.reduce((sum,line)=>sum+shop.products.find(p=>p.id===line.productId).price*line.quantity,0);return {subtotal,total:subtotal+190};}if(name==='role_checkout'){paid++;assert.equal(args.p_total,5090);assert.equal(args.p_topup,true);return {order:{id:'beef-order',shop_name:shop.name,total:5090,subtotal:4900,delivery:190,discount:0,items:args.p_lines.map(line=>({...shop.products.find(p=>p.id===line.productId),quantity:line.quantity})),note:'角色点餐：为凑起送价增加商品或份数'}};}throw Error('unexpected '+name);};const card=await t.ctx.northPreferredRoleFood(t.c,'宋式番茄炖牛腩','37|闲云野鹤居|无|热的|1','main',{messageId:'beef-request',userText:'那我要吃宋式番茄炖牛腩',northCurrentRequest:true});assert.equal(card.type,'marketfood');assert.equal(paid,1);assert.equal(quoted.reduce((sum,line)=>sum+line.quantity,0),3);assert.equal(quoted.find(line=>line.productId==='beef').quantity,1);assert.equal(quoted.find(line=>line.productId==='rice').quantity,1);assert.equal(quoted.find(line=>line.productId==='lotus').quantity,1);t.ctx.msgs=()=>[card];assert.equal(await t.ctx.northPreferredRoleFood(t.c,'宋式番茄炖牛腩','37','main',{messageId:'beef-request'}),null);assert.equal(paid,1);});
 test((priv?'private':'web')+' fixed dessert intent carries original menu and explicit builtin needs no cloud wallet',async()=>{const t=roleContext(),builtin={window:{}};vm.runInNewContext(fs.readFileSync('assets/north-dessert-shop.js','utf8'),builtin);t.ctx.northBuiltinShops=()=>builtin.window.NorthBuiltinShops;t.ctx.northMerchantSaved=()=>null;let received;t.ctx.northRoleModel=async(c,task,payload)=>{received=payload.localMenus;return JSON.stringify(received?{order:true,name:'蓝莓小蛋糕',shop:'NORTH甜品店',specs:'无',temperature:'不适用',quantity:1}:{order:true,name:'蓝莓小蛋糕',body:'15|NORTH甜品店|无|不适用|1'});};const repaired=await t.ctx.northRoleEnsureAction(t.c,'乖，嘴倒是甜了。喝口水，等着。','我想吃蓝莓小蛋糕给我点',{messageId:'fixed',northCurrentRequest:true});assert.ok(received,'intent classifier must receive original local menus rather than invent prices');assert.match(repaired,/\[点外卖\|蓝莓小蛋糕\|15\|NORTH甜品店\|无\|不适用\|1\]/);t.ctx.northRoleFoodCard=()=>({id:'local-fixed',type:'food',from:'ta'});t.ctx.northMarketRpc=async()=>{throw Error('cloud is offline');};const meta={messageId:'fixed',northCurrentRequest:true};const first=await t.ctx.northPreferredRoleFood(t.c,'蓝莓小蛋糕','15|NORTH甜品店|无|不适用|1','main',meta);assert.equal(first.type,'food','explicit builtin must not depend on cloud wallet');assert.equal(t.paid(),0);t.ctx.msgs=()=>[first];assert.equal(await t.ctx.northPreferredRoleFood(t.c,'蓝莓小蛋糕','15|NORTH甜品店|无|不适用|1','main',meta),null);});
