test('portable shop package preserves editable groups and specs without importing money, credentials or stock',()=>{for(const prefix of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/']){const source=fs.readFileSync(prefix+'commerce-ui.js','utf8');let count=0;const ctx={window:{},Map,Set,JSON,uid:()=> 'new-'+(++count),actId:()=> 'buyer'};vm.createContext(ctx);const start=source.indexOf('  function northMerchantPackImage('),end=source.indexOf('  async function northMerchantPortableImage(',start);assert.ok(start>=0);vm.runInContext(source.slice(start,end)+source.split('\n').filter(l=>l.startsWith('  function northMerchantProductError(')||l.startsWith('  function northMerchantError(')).join('\n'),ctx);const shop={name:'甜品店',category:'甜品',tags:['甜品'],intro:'自定义',cover:'',minimum:1500,delivery:190,deliveryMinutes:30,groups:[{id:'cake',name:'蛋糕'}],products:[{id:'old',name:'蓝莓小蛋糕',groupId:'cake',price:1500,unit:'份',image:'',stock:99,signature:true,specGroups:[{id:'size',name:'分量',mode:'single',required:true,options:[{id:'one',label:'小份',price:0,default:true}]}]}],defaultSpecGroups:[],owner:'seller',balance:50000,secret:'private',marketId:' чужой'};const pack={format:'north-shop-pack',version:1,shop},current={id:'local',revision:7,marketId:'own-cloud',marketRevision:3};const d=ctx.northMerchantPackParse(pack,current);assert.equal(d.name,shop.name);assert.equal(d.marketId,'own-cloud');assert.equal(d.owner,'buyer');assert.equal(d.status,'draft');assert.equal(d.revision,7);assert.equal(d.products[0].groupId,d.groups[0].id);assert.equal(d.products[0].specGroups[0].options[0].label,'小份');assert.equal(d.products[0].stock,undefined);assert.equal(d.balance,undefined);assert.equal(d.secret,undefined);assert.notEqual(d.products[0].id,'old');assert.throws(()=>ctx.northMerchantPackParse({...pack,version:2},current));assert.throws(()=>ctx.northMerchantPackParse({...pack,shop:{...shop,cover:'javascript:alert(1)'}},current));assert.throws(()=>ctx.northMerchantPackParse({...pack,shop:{...shop,products:[{...shop.products[0],price:-1}]}},current));}});

