test('merchant products move exactly one displayed row without changing IDs or saved account data',()=>{for(const prefix of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/']){const src=fs.readFileSync(prefix+'commerce-ui.js','utf8'),fn=src.split('\n').find(l=>l.startsWith('  window.northMerchantProductMove='));assert.ok(fn,'product move handler missing');const products=[{id:'a',groupId:'g',price:100},{id:'other',groupId:'h',price:900},{id:'b',groupId:'g',price:200},{id:'c',groupId:'g',price:300}],view={screen:'editor',draft:{products:JSON.parse(JSON.stringify(products))},dirty:false};let refreshed=0,active=true;const ctx={window:{},northMerchantView:view,northMerchantActive:()=>active,northSaving:false,northMarketBusy:false,northProductEdit:null,northMerchantRefresh:()=>refreshed++};vm.createContext(ctx);vm.runInContext(fn,ctx);ctx.window.northMerchantProductMove('a',-1);assert.equal(view.dirty,false);ctx.window.northMerchantProductMove('b',-1);assert.deepEqual(view.draft.products.map(p=>p.id),['a','b','other','c']);assert.equal(view.dirty,true);assert.equal(refreshed,1);assert.deepEqual(view.draft.products.find(p=>p.id==='b'),products[2]);ctx.window.northMerchantProductMove('a',1);assert.deepEqual(view.draft.products.map(p=>p.id),['b','a','other','c']);const unchanged=JSON.stringify(view.draft.products);ctx.northSaving=true;ctx.window.northMerchantProductMove('a',-1);ctx.northSaving=false;active=false;ctx.window.northMerchantProductMove('a',-1);assert.equal(JSON.stringify(view.draft.products),unchanged);assert.equal(products[0].id,'a');}});

test('App store lookup runs only as a role action and binds a shop-name followup to the unfulfilled meal request',async()=>{for(const prefix of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/']){const src=fs.readFileSync(prefix+'commerce-ui.js','utf8');assert.ok(src.includes('function northRoleAppShopQuery('),'missing internal App shop tool');const c={id:'partner'},messages=[{id:'meal',role:'user',type:'text',content:'那我要吃宋式番茄炖牛腩和山房小炒肉',time:Date.now()-180000},{id:'ask',role:'assistant',type:'text',content:'哪家店，报名字。',time:Date.now()-170000},{id:'shop',role:'user',type:'text',content:'闲云野鹤居',time:Date.now()}],state={};let calls=[];const ctx={S:state,Date,JSON,Math,Set,actId:()=> 'main',msgs:()=>messages,northData:()=>({}),northMarketCoupleRole:()=>c,deliveryRealEnabled:()=>false,northMarketRpc:async(name,args)=>{calls.push(name);if(name==='list'){assert.equal(args.p_query,'闲云野鹤居');return {shops:[{id:'store',name:'闲云野鹤居'}]};}return {shop:{id:'store',name:'闲云野鹤居',minimum:4800,delivery:190},products:[{id:'beef',name:'宋式番茄炖牛腩',price:3700,stock:2,specGroups:[],available:true},{id:'pork',name:'山房小炒肉',price:3900,stock:2,specGroups:[],available:true}]};}};vm.createContext(ctx);vm.runInContext(src.split('\n').filter(l=>/^  (function northRoleShortBuyContext|function northRoleOrderRequest|async function northRoleAppShopQuery)/.test(l)).join('\n'),ctx);const request=ctx.northRoleOrderRequest(c,'闲云野鹤居');assert.equal(request.anchorId,'meal');assert.match(request.text,/宋式番茄炖牛腩和山房小炒肉/);assert.deepEqual(calls,[],'context binding must not automatically search');const result=await ctx.northRoleAppShopQuery(c,'闲云野鹤居');assert.equal(result.ok,true);assert.deepEqual(calls,['list','shop']);assert.equal(result.shops[0].products.length,2);assert.equal(result.shops[0].products[0].price,3700);assert.match(result.prompt,/App内/);assert.doesNotMatch(result.prompt,/苏州没有|早上不能/);}});

